public record Move(int Row, int Col, Player Player);

public class GameWithHistory : Game
{
    private readonly Stack<Move> _history = new();

    public bool Undo()
    {
        if (_history.Count == 0) return false;
        var last = _history.Pop();
        Board.UndoPlace(last.Row, last.Col);
        Winner = null;
        CurrentPlayer = last.Player;
        return true;
    }

    public new bool Play(int row, int col)
    {
        if (base.Play(row, col))
        {
            _history.Push(new Move(row, col, CurrentPlayer));
            return true;
        }
        return false;
    }
}

public class TicTacToeAI
{
    public (int row, int col)? GetBestMove(Board board, Player aiPlayer)
    {
        Player human = aiPlayer == Player.X ? Player.O : Player.X;
        var (score, move) = Minimax(board, aiPlayer, human, 0);
        return move;
    }

    private (int score, (int, int)? move) Minimax(Board board, Player ai, Player human, int depth)
    {
        if (board.CheckWinner() == ai) return (10 - depth, null);
        if (board.CheckWinner() == human) return (depth - 10, null);
        if (board.IsFull) return (0, null);

        (int row, int col)? bestMove = null;
        int bestScore = int.MinValue;

        foreach (var cell in board.GetEmptyCells())
        {
            board.Place(cell.row, cell.col, ai);
            var (score, _) = Minimax(board, human, ai, depth + 1);
            board.UndoPlace(cell.row, cell.col);

            if (score > bestScore)
            {
                bestScore = score;
                bestMove = (cell.row, cell.col);
            }
        }
        return (bestScore, bestMove);
    }
}
